test('błąd wykonania zachowuje wcześniejszy rysunek', () => {
  const result = run('np 10 np 1 / 0', '2d');
  expect(result.segments.length).toBe(1);
  expect(result.error?.line).toBe(1);
});
test('powtórzenie rysuje kwadrat', () => {
  const result = run('powtorz 4 [np 100 pw 90]', '2d');
  expect(result.error).toBeNull();
  expect(result.segments.length).toBe(4);
  expect(result.segments[3].to[0]).toBeCloseTo(0);
  expect(result.segments[3].to[1]).toBeCloseTo(0);
});
EOF
